import { applicatures } from 'app/services/KeyboardService/mappings';
import { scaleApplicatures } from 'app/services/KeyboardService/scaleApplicatures';
import { chromaticNotes } from 'app/services/NotesService/chromaticNotes';
import { splitNote } from 'app/services/NotesService/noteUtils';
import type { JustNote, Note, Octave } from 'app/services/NotesService/types';
import { isMicrotonalScale } from 'app/services/SettingsService/microtonal';
import {
  Mode,
  Scale,
  getScale,
  scales,
} from 'app/services/SettingsService/scales';

import type { Melody } from './types';

export type MelodyScaleSettings = Pick<
  Melody,
  | 'scale'
  | 'mode'
  | 'pitch'
  | 'octave'
  | 'customScale'
  | 'keyboardLayout'
  | 'keyboardStart'
>;

const noteNumber = (note: Note) => {
  const [name, octave] = splitNote(note);
  return octave * 12 + chromaticNotes.indexOf(name);
};
const mod = (value: number) => ((value % 12) + 12) % 12;

/** Index on the actual repeating keyboard, not just pitch-class membership. */
export const melodyKeyIndices = (
  melody: Pick<Melody, 'notes'> & MelodyScaleSettings,
) => {
  const intervals = getScale(melody.scale, melody.mode, melody.customScale).map(
    note => chromaticNotes.indexOf(note),
  );
  const origin = melody.keyboardStart
    ? noteNumber(melody.keyboardStart)
    : melody.octave * 12 + melody.pitch;
  return melody.notes.map(({ note }) => {
    const offset = noteNumber(note) - origin;
    const degree = intervals.indexOf(mod(offset));
    return degree < 0
      ? -1
      : Math.floor(offset / 12) * intervals.length + degree;
  });
};

export const isMelodyKeyboardPlayable = (melody: Melody) => {
  const count = melody.keyboardLayout
    ? applicatures.totalQwertyMac.length
    : scaleApplicatures[melody.scale].length;
  return melodyKeyIndices(melody).every(index => index >= 0 && index < count);
};

/** Smallest supported scale containing every pitch; never changes the score.
 * Keep a conventional scale where possible. Chromatic exceptions use only
 * the composition's own pitch classes instead of twelve unnecessary steps. */
export const optimizeMelodyScale = (melody: Melody): Melody => {
  if (isMicrotonalScale(melody.scale)) return melody;
  if (!melody.notes.length || melody.timbre === 'drums') return melody;
  if (melody.scale === 'elevenTone' && isMelodyKeyboardPlayable(melody))
    return melody;
  const uniqueNotes = Array.from(
    new Map(melody.notes.map(note => [note.note, note])).values(),
  );
  const pitches = uniqueNotes.map(({ note }) => noteNumber(note));
  const classes = Array.from(new Set(pitches.map(mod))).sort((a, b) => a - b);
  // A curated eight-or-more-note scale already reaches the pitch-class lower
  // bound. Keep its tonic and fingering when every note remains playable.
  if (
    melody.scale === 'custom' &&
    classes.length > 7 &&
    melody.customScale?.length === classes.length &&
    isMelodyKeyboardPlayable(melody)
  )
    return melody;
  const low = Math.min(...pitches);
  const makeSettings = (
    scale: Scale,
    mode: Mode,
    root: number,
    octave: number,
  ): MelodyScaleSettings => {
    const sameRoot = root === mod(melody.pitch);
    const originalOctave = octave + (root - melody.pitch) / 12;
    const keepPitch = sameRoot && originalOctave >= 0 && originalOctave <= 8;
    return {
      scale,
      mode,
      pitch: melody.pitch,
      octave: (keepPitch ? originalOctave : octave) as Octave,
      keyboardStart: keepPitch
        ? undefined
        : (`${chromaticNotes[root]}${octave}` as Note),
      keyboardLayout: undefined,
      customScale: undefined,
    };
  };
  const candidates: {
    settings: MelodyScaleSettings;
    size: number;
    span: number;
    preference: number;
  }[] = [];
  (Object.keys(scales) as Scale[])
    .filter(
      scale =>
        scale !== 'custom' &&
        scale !== 'elevenTone' &&
        !isMicrotonalScale(scale),
    )
    .forEach(scale => {
      scales[scale].modes.forEach(mode => {
        const intervals = getScale(scale, mode).map(note =>
          chromaticNotes.indexOf(note),
        );
        for (let root = 0; root < 12; root++) {
          if (!classes.every(pitch => intervals.includes(mod(pitch - root))))
            continue;
          const octave = Math.floor((low - root) / 12);
          if (octave < 0 || octave > 8) continue;
          const settings = makeSettings(scale, mode, root, octave);
          const indices = melodyKeyIndices({
            ...settings,
            notes: uniqueNotes,
          });
          const span = Math.max(...indices) + 1;
          if (span > scaleApplicatures[scale].length)
            settings.keyboardLayout =
              scale === 'chromatic' ? 'full-chromatic' : 'full';
          candidates.push({
            settings,
            size: intervals.length,
            span,
            preference:
              (root === mod(melody.pitch) ? 0 : 2) +
              (scale === melody.scale && mode === melody.mode ? 0 : 1),
          });
        }
      });
    });
  candidates.sort(
    (a, b) =>
      a.size - b.size ||
      Number(a.span > 48) - Number(b.span > 48) ||
      Number(!!a.settings.keyboardLayout) -
        Number(!!b.settings.keyboardLayout) ||
      a.preference - b.preference ||
      a.span - b.span,
  );
  let best = candidates[0];
  // A custom scale is necessary when no conventional non-chromatic scale fits.
  if (!best || (best.settings.scale === 'chromatic' && classes.length < 12)) {
    const root = mod(low);
    const customScale = classes
      .map(pitch => mod(pitch - root))
      .sort((a, b) => a - b)
      .map(index => chromaticNotes[index] as JustNote);
    const settings = {
      ...makeSettings('custom', 'custom', root, Math.floor(low / 12)),
      customScale,
    };
    const span =
      Math.max(...melodyKeyIndices({ ...settings, notes: uniqueNotes })) + 1;
    if (span > scaleApplicatures.custom.length)
      settings.keyboardLayout = 'full';
    best = { settings, size: customScale.length, span, preference: 0 };
  }
  return { ...melody, ...best.settings };
};

