import { chromaticNotes } from './chromaticNotes';
import { JustNote, Note, Octave, Triad, TriadName } from './types';

export const getNote = (justNote: JustNote, octave: Octave): Note =>
  `${justNote}${octave}`;

export const splitNote = (note: Note): [JustNote, Octave] => {
  const noteArray = note.split('');
  const octave = parseInt(noteArray.pop() ?? '', 10);
  return [noteArray.join('') as JustNote, octave as Octave];
};

export const pitchNote = (note: Note, pitch: number): Note => {
  if (pitch === 0) {
    return note;
  }
  const [justNote, octave] = splitNote(note);
  const noteAbsoluteIndex = chromaticNotes.findIndex(n => n === justNote);
  let pitchedNoteIndex = noteAbsoluteIndex + pitch;
  let deltaOctave = 0;

  if (pitchedNoteIndex < 0) {
    pitchedNoteIndex = chromaticNotes.length + pitchedNoteIndex;
    deltaOctave--;
  } else if (pitchedNoteIndex > chromaticNotes.length - 1) {
    pitchedNoteIndex = pitchedNoteIndex - chromaticNotes.length;
    deltaOctave++;
  }

  return getNote(
    chromaticNotes[pitchedNoteIndex],
    (octave + deltaOctave) as Octave,
  );
};

export const getChord = (note: Note, triad: TriadName): Triad => [
  note,
  pitchNote(note, triad === 'major' ? 4 : 3),
  pitchNote(note, 7),
];
