import { chromaticNotes } from 'app/services/NotesService/chromaticNotes';
import type { JustNote, Note } from 'app/services/NotesService/types';

// Fixed, transposable models. Sources and performance limits: docs/MICROTONAL.md.
export const microtonalPresets = {
  huseyni35: {
    label: 'Хюсейни · −35 центов',
    cents: [0, 165, 300, 500, 700, 865, 1000],
  },
  huseyni15: {
    label: 'Хюсейни · −15 центов',
    cents: [0, 185, 300, 500, 700, 885, 1000],
  },
  rast24: {
    label: 'Раст · четвертитоновая модель',
    cents: [0, 200, 350, 500, 700, 900, 1050],
  },
  bayati24: {
    label: 'Баяти · четвертитоновая модель',
    cents: [0, 150, 300, 500, 700, 800, 1000],
  },
} as const;

export type MicrotonalMode = keyof typeof microtonalPresets;
export const microtonalGroups = {
  turkishMakam: ['huseyni35', 'huseyni15'],
  neyMakam: ['huseyni15', 'huseyni35'],
  quarterMaqam: ['rast24', 'bayati24'],
} as const;
export type MicrotonalScale = keyof typeof microtonalGroups;

export const microtonalInstruments = {
  turkishGuitar: { scale: 'turkishMakam' },
  oud: { scale: 'quarterMaqam' },
  ney: { scale: 'neyMakam' },
} as const;
export type MicrotonalTimbre = keyof typeof microtonalInstruments;

export const microtonalInstrument = (timbre: string) =>
  Object.prototype.hasOwnProperty.call(microtonalInstruments, timbre)
    ? microtonalInstruments[timbre as MicrotonalTimbre]
    : undefined;

export const isMicrotonalScale = (scale: string): scale is MicrotonalScale =>
  Object.prototype.hasOwnProperty.call(microtonalGroups, scale);

export const microtonalPreset = (scale: string, mode: string) => {
  if (!isMicrotonalScale(scale)) return undefined;
  const modes = microtonalGroups[scale] as readonly MicrotonalMode[];
  return microtonalPresets[modes.find(m => m === mode) ?? modes[0]];
};

export const microtonalNotes = (scale: string, mode: string) =>
  microtonalPreset(scale, mode)?.cents.map(
    cents => chromaticNotes[Math.round(cents / 100)],
  );

export const noteTuningCents = (
  note: Note,
  settings: { scale: string; mode: string; pitch: number },
) => {
  const preset = microtonalPreset(settings.scale, settings.mode);
  if (!preset) return 0;
  const semitone = chromaticNotes.indexOf(note.slice(0, -1) as JustNote);
  const relative = (((semitone - settings.pitch) % 12) + 12) % 12;
  const cents = (preset.cents as readonly number[]).find(
    c => Math.round(c / 100) === relative,
  );
  return cents === undefined ? 0 : cents - relative * 100;
};

export const tuningLabel = (cents: number) =>
  `${cents < 0 ? '−' : '+'}${Math.abs(cents).toFixed(1).replace(/\.0$/, '')}¢`;
