import { chromaticNotes } from '../NotesService/chromaticNotes';
import type { Note } from '../NotesService/types';
import {
  MicrotonalTimbre,
  microtonalInstruments,
} from '../SettingsService/microtonal';
import microtonalMap from './generated/microtonalMap.json';
import sampleMap from './generated/sampleMap.json';
import { LibraryTimbre, SampleDefinition, Timbre, TimbreLink } from './types';

const legacyAliases: Partial<Record<Timbre, LibraryTimbre>> = {
  turkishGuitar: 'acClassy6Str',
  celeste: 'glockenspiel',
  bass: 'EBM Bass',
  harpsichord: 'pizzicato',
  horn: 'trumpet',
  sine: 'warmPad',
  square: '8bit',
  triangle: 'warmPad',
  sawtooth: 'synthLead',
  custom: 'synthLead',
};
export const sampleDefinition = (timbre: Timbre): SampleDefinition =>
  microtonalMap[timbre as keyof typeof microtonalMap] ??
  sampleMap[legacyAliases[timbre] ?? (timbre as LibraryTimbre)] ??
  sampleMap.studioResonantPiano;
export const fixedNotesFor = (timbre?: Timbre): Note[] | undefined =>
  timbre
    ? sampleDefinition(timbre).pitchedNotes?.map(
        ({ index }) =>
          `${chromaticNotes[index % 12]}${Math.floor(index / 12)}` as Note,
      )
    : undefined;
const labels: Partial<Record<Timbre, string>> = {
  guitar: 'Гитара',
  distortedGuitar: 'Электрогитара с перегрузом',
};
export const timbresLinks: TimbreLink[] = (
  [...Object.keys(sampleMap), ...Object.keys(microtonalInstruments)] as (
    | LibraryTimbre
    | MicrotonalTimbre
  )[]
).map(title => ({
  title,
  label: labels[title],
  link: `/samples/library/${sampleDefinition(title).file}`,
  setup:
    title === 'drums'
      ? 'drums'
      : sampleDefinition(title).articulations
      ? 'articulations'
      : 'piano',
}));
export const timbres: Timbre[] = timbresLinks.map(({ title }) => title);
